using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "AugmentedWelding", menuName = "Data/Battle/Effects/Hevelius/AugmentedWelding Effect")]
public class AugmentedWeldingEffect : Effect
{
	[SerializeField]
	private OmenLogic omenLogic;

	public override void Initialize(int effectAmount, GameObject effectOwner, GameObject source)
	{
		effectOwner.GetComponent<CompanionCorruptionStats>().InitializeAugmentedWelding();
		effectOwner.GetComponent<CompanionCorruptionStats>().IncreaseMaxCorruption(effectAmount);
		omenLogic.ActivateOmen(null, Mathf.FloorToInt(effectOwner.GetComponent<CompanionCorruptionStats>().MaxCorruption / 2f), null, null);
	}

	public override void EffectIncreased(int effectAmount, GameObject effectOwner, GameObject source)
	{
		effectOwner.GetComponent<CompanionCorruptionStats>().IncreaseMaxCorruption(effectAmount);
		omenLogic.ActivateOmen(null, Mathf.FloorToInt(effectOwner.GetComponent<CompanionCorruptionStats>().MaxCorruption / 2f), null, null);
	}
}
